-- Properties a contact enquired about (from the "REF: nnn" lines in their enquiry notes). New enquiries add to it automatically.
CREATE TABLE IF NOT EXISTS contact_refs (contact_id INTEGER NOT NULL, reference TEXT NOT NULL, PRIMARY KEY(contact_id,reference));
CREATE INDEX IF NOT EXISTS idx_po_contact ON property_owners(contact_id);
